<?php session_start();require 'config.php';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$n=trim($_POST['name']??'');$e=trim($_POST['email']??'');$p=$_POST['password']??'';if(!$n||!filter_var($e,FILTER_VALIDATE_EMAIL)||strlen($p)<6)$msg='اطلاعات را درست وارد کنید.';else{$h=password_hash($p,PASSWORD_DEFAULT);$s=$conn->prepare('INSERT INTO users(name,email,password_hash) VALUES(?,?,?)');$s->bind_param('sss',$n,$e,$h);if($s->execute()){$_SESSION['user_id']=$s->insert_id;header('Location:index.php');exit;}$msg='این ایمیل قبلاً ثبت شده است.';}}?><!doctype html><html lang='fa' dir='rtl'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>ثبت‌نام</title><link rel='stylesheet' href='style.css'></head><body><main class='formbox'><h1>🎓 ثبت‌نام</h1><p class='error'><?=htmlspecialchars($msg)?></p><form method='post'><input name='name' placeholder='نام' required><input name='email' type='email' placeholder='ایمیل' required><input name='password' type='password' placeholder='رمز عبور' required><button class='btn'>ثبت‌نام</button></form><a href='login.php'>ورود به حساب</a></main></body></html>